package gen

import (
	"bytes"
	"fmt"
	"strings"

	"github.com/junikimm717/static-python/src/staticpy/internal/assets"
	"github.com/junikimm717/static-python/src/staticpy/internal/config"
)

// sectionMarker splits the Setup asset into module sets. Everything before the
// first marker is the makesetup preamble and is always emitted.
const sectionMarker = "#staticpy:section "

// The staticapi module is the whole reason ctypes works in a static build; the
// symbols.c half is generated by StaticAPI, not shipped.
const staticapiLine = "staticapi staticapi/symbols.c staticapi/staticapi.c"

// SetupLocal renders Modules/Setup.local: the preamble and module sections from
// the Setup asset, the staticapi module, then one line per bundled extension.
//
// Modules == "minimal" is the pyhost set: no OpenSSL, no libffi, no sqlite, not
// even zlib. deepfreeze.py imports only pure-Python modules, and
// freeze_modules.py's hashlib falls back to the builtin _sha2/_md5.
func SetupLocal(cfg config.Resolved, extra []config.PyModule) ([]byte, error) {
	preamble, sections, err := parseSetupAsset(assets.MustGet("Setup"))
	if err != nil {
		return nil, err
	}

	want := []string{"core"}
	switch cfg.Modules {
	case "", "full":
		want = append(want, "full")
	case "minimal":
	default:
		return nil, fmt.Errorf("gen: unknown module set %q", cfg.Modules)
	}
	if cfg.TestModules {
		want = append(want, "test")
	}

	var b bytes.Buffer
	b.WriteString("# Generated by staticpy. Edits here are lost on the next build.\n")
	fmt.Fprintf(&b, "# profile=%s scope=%s modules=%s test_modules=%t\n\n",
		cfg.Profile, cfg.Scope, orFull(cfg.Modules), cfg.TestModules)
	b.Write(preamble)

	for _, name := range want {
		body, ok := sections[name]
		if !ok {
			return nil, fmt.Errorf("gen: Setup asset has no %q section", name)
		}
		b.Write(body)
	}

	// pyhost never imports ctypes, so the 900-entry symbol table is pure weight
	// there.
	if cfg.Modules != "minimal" {
		b.WriteString("\n" + staticapiLine + "\n")
	}

	if len(extra) > 0 {
		b.WriteString("\n# Bundled packages\n\n*static*\n\n")
		for _, m := range extra {
			line, err := moduleLine(m)
			if err != nil {
				return nil, err
			}
			b.WriteString(line + "\n")
		}
	}
	return b.Bytes(), nil
}

func orFull(m string) string {
	if m == "" {
		return "full"
	}
	return m
}

// moduleLine renders one makesetup line. A dotted module is registered under its
// flattened builtin name; see BuiltinName.
func moduleLine(m config.PyModule) (string, error) {
	name := BuiltinName(m.Name)
	if !cIdent.MatchString(name) {
		return "", fmt.Errorf("gen: module %q has no valid builtin name", m.Name)
	}
	if len(m.Sources) == 0 {
		return "", fmt.Errorf("gen: module %q has no sources", m.Name)
	}
	parts := append([]string{name}, m.Sources...)
	parts = append(parts, m.CFlags...)
	parts = append(parts, m.Libs...)
	for _, p := range parts {
		if strings.ContainsAny(p, " \t\n") {
			return "", fmt.Errorf("gen: module %q: makesetup cannot express the argument %q", m.Name, p)
		}
	}
	return strings.Join(parts, " "), nil
}

func parseSetupAsset(src []byte) ([]byte, map[string][]byte, error) {
	known := map[string]bool{"core": true, "full": true, "test": true}
	sections := map[string][]byte{}

	preamble := &bytes.Buffer{}
	bufs := map[string]*bytes.Buffer{}
	cur := preamble
	for _, line := range strings.SplitAfter(string(src), "\n") {
		rest, isMarker := strings.CutPrefix(line, sectionMarker)
		if !isMarker {
			cur.WriteString(line)
			continue
		}
		name := strings.TrimSpace(rest)
		if !known[name] {
			return nil, nil, fmt.Errorf("gen: Setup asset names unknown section %q", name)
		}
		if _, dup := bufs[name]; dup {
			return nil, nil, fmt.Errorf("gen: Setup asset repeats section %q", name)
		}
		cur = &bytes.Buffer{}
		bufs[name] = cur
	}
	for n, buf := range bufs {
		sections[n] = buf.Bytes()
	}
	return preamble.Bytes(), sections, nil
}
